config.render:
function (v) {
  var pv = v.visits * 1;
  var bounced = Math.round(v.visits * v.bounce / 100);
  var converted = Math.round(v.visits * v.cvr / 100);
  var note = "";
  if (v.cvr < 5) note = "معدل التحويل منخفض — راجع تجربة المستخدم في رحلة الإجراء المستهدف.";
  else if (v.cvr > 15) note = "معدل تحويل جيد — حافظ على تجربة الاستخدام الحالية.";
  else note = "معدل التحويل متوسط — جمع أدلة نوعية لفهم أين يتوقف المستخدمون.";
  return '<div class="pg-stat"><b>' + pv + '</b><span>مشاهدات الصفحة PV</span></div>' +
    '<div class="pg-stat warn"><b>' + v.bounce + '%</b><span>معدل الارتداد (وفق تعريف الأداة)</span></div>' +
    '<div class="pg-stat ok"><b>' + v.cvr + '%</b><span>معدل التحويل CVR</span></div>' +
    '<p style="width:100%;font-size:.85rem;color:var(--text-muted)">' + note + '</p>';
}

function (vals) {
  var ra = vals.a.users ? Math.round(vals.a.clicks / vals.a.users * 1000) / 10 : 0;
  var rb = vals.b.users ? Math.round(vals.b.clicks / vals.b.users * 1000) / 10 : 0;
  var winner = ra === rb ? "تعادل — نحتاج عينة أكبر" : (ra > rb ? "النسخة A" : "النسخة B");
  var max = Math.max(ra, rb, 1);
  return '<div class="pg-ab-result"><p>معدل التحويل — A: <b>' + ra + '%</b> | B: <b>' + rb + '%</b></p>' +
    '<div class="pg-ab-bar"><span style="width:' + (ra / max * 100) + '%;background:var(--primary)"></span></div>' +
    '<div class="pg-ab-bar"><span style="width:' + (rb / max * 100) + '%;background:var(--warning)"></span></div>' +
    '<p class="winner">الأفضل وفق المقياس: ' + winner + ' — وراجع كفاية العينة قبل تعميم النتيجة.</p></div>';
}
